@Service
public class InvoicePricingService {

    private final ExchangeRateClient exchangeRateClient;
    private final ConcurrentHashMap<String, BigDecimal> rateCache = new ConcurrentHashMap<>();

    public InvoicePricingService(ExchangeRateClient exchangeRateClient) {
        this.exchangeRateClient = exchangeRateClient;
    }

    @PostConstruct
    void warmUpCache() {
        rateCache.putAll(exchangeRateClient.fetchInitialRates());
    }

    @PreDestroy
    void shutdown() {
        exchangeRateClient.close();
    }

    public BigDecimal convert(String currency, BigDecimal amount) {
        return amount.multiply(rateCache.getOrDefault(currency, BigDecimal.ONE));
    }
}

